<script lang="ts">
 import MailNav from '$lib/components/newsletter/MailNav.svelte';let {data}=$props();let period=$state('90');
 const rate=(n:number,d:number)=>d?(n/d*100).toFixed(1)+'%':'—';
 let reports=$derived(data.reports.filter((r:any)=>period==='all'||Date.parse(r.scheduled_at??r.created_at)>=Date.now()-Number(period)*86400000));
 let totals=$derived(reports.reduce((sum:Record<string,number>,r:any)=>{for(const key of ['total','sent','delivered','opened','clicked','failed','queued'])sum[key]=(sum[key]??0)+Number(r[key]??0);return sum;},{} as Record<string,number>));
 function exportCsv(){const columns=['メール名','件名','対象','送信受付','到達','開封','クリック','失敗・要確認','待機中'];const cell=(v:unknown)=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=reports.map((r:any)=>[r.name,r.subject,r.total,r.sent,r.delivered,r.opened,r.clicked,r.failed,r.queued]);const blob=new Blob(['\uFEFF'+[columns,...rows].map((row:unknown[])=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='newsletter-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<svelte:head><title>配信レポート ｜ メルマガ</title></svelte:head><MailNav active="reports"/><h1 class="mb-3 text-2xl font-semibold">配信レポート</h1><p class="mb-6 text-sm text-stone-500">テストメールを除く本配信の集計です。開封・クリックはResendで追跡を有効にした場合に表示されます。受信側のプライバシー保護により、実際の閲覧と一致しないことがあります。</p><div class="mb-5 flex flex-wrap items-center gap-3"><label class="text-sm">集計期間<select class="ml-2 rounded-lg border p-3" bind:value={period}><option value="30">過去30日</option><option value="60">過去60日</option><option value="90">過去90日</option><option value="all">全期間</option></select></label><button class="min-h-11 rounded-lg border px-4 text-sm" disabled={!reports.length} onclick={exportCsv}>CSVを書き出す</button></div><p class="mb-4 text-sm text-stone-500">最新200キャンペーンから、配信予定日（未設定は作成日）で絞り込んでいます。</p><div class="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">{#each [['到達',totals.delivered??0],['開封率',rate(totals.opened??0,totals.delivered??0)],['クリック率',rate(totals.clicked??0,totals.delivered??0)],['失敗・要確認',totals.failed??0]] as [label,value]}<section class="rounded-xl border border-stone-200 bg-white p-5"><p class="text-sm text-stone-500">{label}</p><p class="mt-2 text-3xl font-semibold">{value}</p></section>{/each}</div><div class="overflow-auto rounded-xl border border-stone-200 bg-white"><table class="w-full text-left text-sm"><thead class="bg-stone-50"><tr><th>メール</th><th>対象</th><th>送信受付</th><th>到達</th><th>開封</th><th>クリック</th><th>失敗・要確認</th><th>待機中</th></tr></thead><tbody>{#each reports as r}<tr class="border-t border-stone-100"><td><a class="font-medium underline" href={'/admin/mail/'+r.id}>{r.name}</a><p class="mt-1 text-stone-500">{r.subject}</p></td><td>{r.total}</td><td>{r.sent}</td><td>{r.delivered}</td><td>{r.opened}<small>{rate(r.opened,r.delivered)}</small></td><td>{r.clicked}<small>{rate(r.clicked,r.delivered)}</small></td><td>{r.failed}</td><td>{r.queued}</td></tr>{:else}<tr><td colspan="8">配信データはまだありません。Benchmarkの過去の配信データは移行しません。</td></tr>{/each}</tbody></table></div><style>th,td{padding:16px;white-space:nowrap}small{display:block;color:#78716c;font-size:14px;margin-top:4px}</style>
